import json,numpy as np
from PIL import Image
import sys
p=sys.argv[1]
m=json.load(open(p+'/meta.json'))
for cam in ['head_camera','front_camera']:
 im=np.array(Image.open(p+'/last/'+cam+'.jpg')).astype(float);d=np.load(p+'/depth_'+cam+'.npy').astype(float)
 K=np.array(m['cameras'][cam]['intrinsic_cv']);T=np.array(m['cameras'][cam]['cam2world_gl'])
 for name,mask in [('red',(im[:,:,0]>130)&(im[:,:,1]<80)&(im[:,:,2]<80)),('blue',(im[:,:,2]>100)&(im[:,:,0]<80)&(im[:,:,1]<100))]:
  v,u=np.where(mask);z=d[v,u]; pts=np.stack([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z],1)@T[:3,:3].T+T[:3,3]
  print(cam,name,'pixels',len(u),'range',np.min(pts,0),np.max(pts,0),'median',np.median(pts,0),'quantile',np.quantile(pts,[.05,.95],axis=0))
PY
